-- Setiembre 2026 publicado por GeoBosques (PNCB_ATD_UTM_01_273).
-- Entra a la búsqueda del visor. No pisa un código ni un origen que ya exista.
SET search_path = atd, public;


SELECT 'geobosques_2026', now(),
       (SELECT count(*) FROM alerta
         WHERE origen_gdb = 'geobosques_2026' AND origen_capa = 'PNCB_ATD_UTM_01_273'),
       0, 'ok',
       'Setiembre 2026, raster PNCB_ATD_UTM_01_273'
 WHERE NOT EXISTS (
       SELECT 1 FROM ingesta WHERE fuente = 'geobosques_2026' AND estado = 'ok');
